#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    int findLeastNumOfUniqueInts(std::vector<int>& arr, int k) {
        std::unordered_map<int, int> counts;
        for (int x : arr) counts[x]++;
        std::vector<int> freqs;
        for (auto& [val, count] : counts) freqs.push_back(count);
        std::sort(freqs.begin(), freqs.end());
        int uniqueRem = freqs.size();
        for (int count : freqs) {
            if (k >= count) {
                k -= count;
                uniqueRem--;
            } else {
                break;
            }
        }
        return uniqueRem;
    }
};

import java.util.*;

class Solution {
    public int findLeastNumOfUniqueInts(int[] arr, int k) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int x : arr) counts.put(x, counts.getOrDefault(x, 0) + 1);
        List<Integer> freqs = new ArrayList<>(counts.values());
        Collections.sort(freqs);
        int uniqueRem = freqs.size();
        for (int count : freqs) {
            if (k >= count) {
                k -= count;
                uniqueRem--;
            } else {
                break;
            }
        }
        return uniqueRem;
    }
}

var findLeastNumOfUniqueInts = function(arr, k) {
    const counts = new Map();
    for (const x of arr) counts.set(x, (counts.get(x) || 0) + 1);
    const freqs = Array.from(counts.values()).sort((a, b) => a - b);
    let uniqueRem = freqs.length;
    for (const count of freqs) {
        if (k >= count) {
            k -= count;
            uniqueRem--;
        } else {
            break;
        }
    }
    return uniqueRem;
};
